const end = Date.parse("2026-10-22T17:25:06.061Z") - 5000;
const names = {};
const pat = /^(Duck|Cow|Chicken|Sheep|Goblin|Giant rat|Imp|Man|Woman)$/i;
const log = [];
while (Date.now() < end) {
  if (sdk.getState()?.dialog?.isOpen) await bot.dismissBlockingUI();
  const t = sdk.findNearbyNpc(pat, {reachable:true});
  if (!t) { await sdk.waitForTicks(2); continue; }
  const r = await bot.attack(t);
  if (!r.success) { await sdk.waitForTicks(2); continue; }
  names[t.name]=(names[t.name]||0)+1;
  await sdk.waitForTicks(4);
}
return {names, now: new Date().toISOString()};
